SELECT t.id, t.title, t.detail, t.category, t.priority, t.due_date, t.completed,
       t.created_at, t.updated_at, COALESCE(a.attachment_count, 0) AS attachment_count
FROM todos t
LEFT JOIN (
    SELECT todo_id, COUNT(*) AS attachment_count
    FROM todo_attachments
    GROUP BY todo_id
) a ON a.todo_id = t.id


        AND t.title LIKE CONCAT('%', #{keyword}, '%')


        AND t.category = #{category}


        AND t.due_date >= #{from}


        AND t.due_date <= #{to}


ORDER BY t.due_date ${order}

SELECT id, title, detail, category, priority, due_date, completed, created_at, updated_at
FROM todos
WHERE id = #{id}
